<template>
  <AppLoader v-if="isUsersHiringDashboardLoading" subject="user hiring dashboard" />
  <AppError
    v-else-if="usersHiringDashboardError"
    :error="usersHiringDashboardError"
    title="Failed to load user hiring dashboard"
  />
  <AppEmpty v-else-if="!usersHiringDashboard" subject="user hiring dashboard" />
  <section v-else class="flex flex-col gap-10">
    <PageTitle title="Hiring Dashboard" show-doc />
    <div class="flex flex-col gap-6">
      <Card>
        <CardHeader>
          <CardTitle>Action required</CardTitle>
        </CardHeader>
        <CardContent class="grid grid-cols-4 lg:grid-cols-3 xl:grid-cols-5 gap-4">
          <DashboardCardValue
            v-for="item in action_required"
            :key="item.label"
            :label="item.label"
            :value="item.value || 0"
            :to="item.to"
            class="col-span-4 md:col-span-2 lg:col-span-1 border-blue-600 bg-blue-100"
          />
        </CardContent>
      </Card>
      <Card>
        <CardHeader>
          <CardTitle>Hiring funnel</CardTitle>
        </CardHeader>
        <CardContent class="flex flex-col gap-4 items-center">
          <Card
            v-for="(item, index) in funnel"
            :key="item.label"
            class="w-full border-2"
            :class="{
              'md:w-full border-green-600 bg-green-50': index === 0,
              'md:w-10/12 border-green-600 bg-green-100': index === 1,
              'md:w-8/12 border-green-600 bg-green-200': index === 2,
              'md:w-6/12 border-green-600 bg-green-300': index === 3,
              'md:w-4/12 border-green-600 bg-green-400': index >= 4,
            }"
          >
            <NuxtLink :to="item.to">
              <CardContent class="flex justify-center items-center">
                <span class="text-accent-foreground text-sm md:text-base">{{ item.label }}</span>
                <h3 class="text-2xl md:text-4xl font-semibold line-clamp-1 ml-4 md:ml-8">{{ item.value }}</h3>
              </CardContent>
            </NuxtLink>
          </Card>
        </CardContent>
      </Card>
      <Card>
        <CardHeader>
          <CardTitle>Info</CardTitle>
        </CardHeader>
        <CardContent class="grid grid-cols-4 gap-4">
          <DashboardCardValue
            v-for="item in info"
            :key="item.label"
            :label="item.label"
            :value="item.value || 0"
            :to="item.to"
            class="col-span-4 md:col-span-2 lg:col-span-1"
            :class="{
              'border-red-600 bg-red-100': item.variant === 'error',
              'border-yellow-600 bg-yellow-100': item.variant === 'warning',
            }"
          />
        </CardContent>
      </Card>
    </div>
  </section>
</template>
<script lang="ts" setup>
import { useUsersHiringDashboard } from '~/queries/users/hiring-dashboard';
import DashboardCardValue from '~/components/common/dashboard/DashboardCardValue.vue';
import type { TypedNuxtLink } from '#build/typed-router/typed-router';
import AppEmpty from '~/components/common/AppEmpty.vue';

definePageMeta({
  roles: ['admin'],
  backLabel: 'dashboard',
});

useHead({
  title: 'Hiring Dashboard',
});

const { usersHiringDashboard, usersHiringDashboardError, isUsersHiringDashboardLoading } = useUsersHiringDashboard();

interface DashboardCard {
  label: string;
  value: number | undefined;
  to: TypedNuxtLink['to'];
}

const action_required = computed<DashboardCard[]>(() => [
  {
    label: 'Application not finished',
    value: usersHiringDashboard.value?.action_required.application_not_finished,
    to: { name: 'users', query: { application_completed: 'false', role: 'canvasser', status: 'active' } },
  },
  {
    label: 'Manual Background Check Required',
    value: usersHiringDashboard.value?.action_required.manual_check_required,
    to: { name: 'users', query: { manual_check_required: 'true', role: 'canvasser', status: 'active' } },
  },
  {
    label: 'Social media NOT checked',
    value: usersHiringDashboard.value?.action_required.social_media_not_checked,
    to: {
      name: 'users',
      query: { application_completed: 'true', social_media_checked: 'false', role: 'canvasser', status: 'active' },
    },
  },
]);

const funnel = computed(() => [
  {
    label: 'Application completed',
    value: usersHiringDashboard.value?.hiring_funnel.application_completed,
    to: { name: 'users', query: { application_completed: 'true', role: 'canvasser', status: 'active' } },
  },
  {
    label: 'Background check requested',
    value: usersHiringDashboard.value?.hiring_funnel.background_check_requested,
    to: { name: 'users', query: { background_check_requested: 'true', role: 'canvasser', status: 'active' } },
  },
  {
    label: 'Good to hire',
    value: usersHiringDashboard.value?.hiring_funnel.good_to_hire,
    to: { name: 'users', query: { good_to_hire: 'true', role: 'canvasser', status: 'active' } },
  },
]);

const info = computed(() => [
  {
    label: 'Do NOT Hire',
    value: usersHiringDashboard.value?.info.do_not_hire,
    to: { name: 'users', query: { do_not_hire: 'true', role: 'canvasser' } },
    variant: 'error',
  },
  {
    label: 'Users with Notes',
    value: usersHiringDashboard.value?.info.users_with_notes,
    to: { name: 'users', query: {} },
    variant: 'warning',
  },
]);
</script>
