import { getUsersHiringDashboard, type UsersHiringDashboardResponse } from '~/client';

export const useUsersHiringDashboard = defineQuery(() => {
  const { data, error, isLoading } = useQuery({
    key: () => ['users.hiring.dashboard'],
    query: (): Promise<UsersHiringDashboardResponse> => getUsersHiringDashboard({ composable: '$fetch', body: {} }),
  });

  return {
    usersHiringDashboard: data,
    usersHiringDashboardError: error,
    isUsersHiringDashboardLoading: isLoading,
  };
});
